public static class B1Close {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 required");var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;int count=0;foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name=="B1_SinkSupport")){t.localPosition=new Vector3(Mathf.Sign(t.localPosition.x)*.81f,.51f,Mathf.Sign(t.localPosition.z)*.285f);t.localScale=new Vector3(.038f,.35f,.038f);count++;}
